<?php
const FACILITY_PRIORITIES=['Low','Medium','High','Critical'];
const FACILITY_STATUSES=['New','Under Review','Assigned','In Progress','Awaiting Parts','Pending Vendor','Repair Completed','Awaiting Verification','Verification Failed','Awaiting Approval','Closed','Cancelled','Rejected'];
function facilityH($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function facilityCsrfToken(){if(empty($_SESSION['facility_csrf_token']))$_SESSION['facility_csrf_token']=bin2hex(random_bytes(32));return $_SESSION['facility_csrf_token'];}
function facilityValidateCsrf(){return !empty($_POST['csrf_token'])&&!empty($_SESSION['facility_csrf_token'])&&hash_equals($_SESSION['facility_csrf_token'],$_POST['csrf_token']);}
function facilityHasRole(mysqli $c,int $uid,$roles){if(strtolower($_SESSION['role']??'staff')==='admin')return true;$roles=(array)$roles;if(!$roles)return false;$q=array_map(fn($r)=>"'".mysqli_real_escape_string($c,$r)."'",$roles);$r=mysqli_query($c,"SELECT 1 FROM facility_user_roles WHERE user_id={$uid} AND role_key IN (".implode(',',$q).") LIMIT 1");return $r&&mysqli_num_rows($r)>0;}
function facilityCanManage(mysqli $c,int $uid){return facilityHasRole($c,$uid,['facility_officer','facility_verifier','facility_project_manager','facility_admin']);}
function facilityCanSeeInternal(mysqli $c,int $uid){return facilityHasRole($c,$uid,['facility_officer','facility_technician','facility_verifier','facility_project_manager','facility_admin']);}
function facilityRequestNumber(int $id){return sprintf('MNT-%s-%06d',date('Y'),$id);}
function facilityLog(mysqli $c,int $rid,int $uid,string $action,?string $desc=null){$s=mysqli_prepare($c,"INSERT INTO facility_maintenance_activity_log(maintenance_request_id,user_id,action,description) VALUES (?,?,?,?)");mysqli_stmt_bind_param($s,'iiss',$rid,$uid,$action,$desc);mysqli_stmt_execute($s);}
function facilityNotify(mysqli $c,int $uid,?int $rid,string $type,string $message,?int $assetId=null){if($uid<=0)return;$s=mysqli_prepare($c,"INSERT INTO facility_notifications(user_id,maintenance_request_id,asset_id,type,message) VALUES (?,?,?,?,?)");mysqli_stmt_bind_param($s,'iiiss',$uid,$rid,$assetId,$type,$message);mysqli_stmt_execute($s);}
function facilityStatusClass($s){return match($s){'New'=>'status-new','Under Review'=>'status-review','Assigned'=>'status-assigned','In Progress'=>'status-progress','Awaiting Parts','Pending Vendor'=>'status-wait','Repair Completed','Awaiting Verification'=>'status-verify','Verification Failed','Rejected'=>'status-failed','Awaiting Approval'=>'status-approval','Closed'=>'status-closed','Cancelled'=>'status-cancelled',default=>'status-new'};}
function facilityPriorityClass($p){return 'priority-'.strtolower($p);}
function facilityAssetCode(mysqli $c,int $outletId,int $categoryId){$o='OUT'.$outletId;$r=mysqli_query($c,"SELECT COALESCE(NULLIF(outlet_code,''),CONCAT('OUT',id)) code FROM outlets WHERE id={$outletId} LIMIT 1");if($r&&($x=mysqli_fetch_assoc($r)))$o=preg_replace('/[^A-Z0-9]/','',strtoupper($x['code']));$cat='AST';$r=mysqli_query($c,"SELECT category_code FROM facility_asset_categories WHERE id={$categoryId} LIMIT 1");if($r&&($x=mysqli_fetch_assoc($r)))$cat=preg_replace('/[^A-Z0-9]/','',strtoupper($x['category_code']));$prefix="FAC-{$o}-{$cat}-";$e=mysqli_real_escape_string($c,$prefix);$r=mysqli_query($c,"SELECT MAX(CAST(SUBSTRING_INDEX(asset_code,'-',-1) AS UNSIGNED)) n FROM facility_assets WHERE asset_code LIKE '{$e}%'");$n=($r&&($x=mysqli_fetch_assoc($r)))?(int)($x['n']??0):0;return $prefix.str_pad((string)($n+1),4,'0',STR_PAD_LEFT);}
function facilityNextDate($date,$value,$unit){if(!in_array($unit,['day','week','month','year'],true))$unit='month';$d=new DateTime($date);$d->modify('+'.max(1,(int)$value).' '.$unit);return $d->format('Y-m-d');}
